const r = $json;
if (r.error) return { json: { code: 500, body: { error: 'server_error' } } };
if (!r.found) return { json: { code: 404, body: { error: 'job_not_found' } } };
return { json: { code: 200, body: { versions: Array.isArray(r.versions) ? r.versions : [] } } };

// Validates the edit request before the database or the worker is touched, and keeps only the known fields.
const q = $json.query || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const fail = (code, error) => ({ json: { ok: false, code, body: { error } } });
if (typeof q.id !== 'string' || !UUID.test(q.id)) return fail(404, 'job_not_found');
const b = $json.body;
const isObj = (x) => typeof x === 'object' && x !== null && !Array.isArray(x);
if (!isObj(b)) return fail(400, 'bad_request');
// 200 KB of UTF-8, measured on the parsed body.
const text = JSON.stringify(b);
let bytes = 0;
for (let i = 0; i < text.length; i++) {
  const c = text.charCodeAt(i);
  if (c < 0x80) bytes += 1;
  else if (c < 0x800) bytes += 2;
  else if (c >= 0xd800 && c <= 0xdbff) { bytes += 4; i++; }
  else bytes += 3;
}
if (bytes > 200 * 1024) return fail(413, 'too_large');
if (typeof b.fromVersionId !== 'string' || !UUID.test(b.fromVersionId)) return fail(400, 'bad_request');
if (!isObj(b.cv) || !isObj(b.coverLetter)) return fail(400, 'bad_request');

const pick = (o, keys) => {
  const r = {};
  for (const k of keys) if (Object.prototype.hasOwnProperty.call(o, k)) r[k] = o[k];
  return r;
};
const sub = (x, keys) => (isObj(x) ? pick(x, keys) : x);
const list = (x, f) => (Array.isArray(x) ? x.map(f) : x);
// Empty text for an optional value means "none": stored as null, like every saved document.
const empty = (v) => (typeof v === 'string' && v.trim() === '' ? null : v);
const cvIn = b.cv;
const contact = isObj(cvIn.contact) ? pick(cvIn.contact, ['location', 'email', 'phone', 'links']) : cvIn.contact;
if (isObj(contact)) {
  for (const k of ['location', 'email', 'phone']) if (k in contact) contact[k] = empty(contact[k]);
  if ('links' in contact) contact.links = list(contact.links, (l) => sub(l, ['label', 'url']));
}
const cv = pick(cvIn, ['name', 'headline', 'summary', 'workRights']);
if ('workRights' in cv) cv.workRights = empty(cv.workRights);
if ('contact' in cvIn) cv.contact = contact;
// Government CVs only: competency statements (strings). Standard ATS CVs have no such key.
if ('competencies' in cvIn) cv.competencies = cvIn.competencies;
if ('skills' in cvIn) cv.skills = list(cvIn.skills, (g) => sub(g, ['group', 'items']));
if ('experience' in cvIn) {
  cv.experience = list(cvIn.experience, (e) => {
    const r = sub(e, ['title', 'employer', 'location', 'dates', 'bullets', 'achievements']);
    if (isObj(r) && 'location' in r) r.location = empty(r.location);
    return r;
  });
}
if ('education' in cvIn) cv.education = list(cvIn.education, (e) => sub(e, ['qualification', 'institution', 'dates', 'statusText']));
if ('projects' in cvIn) cv.projects = list(cvIn.projects, (p) => sub(p, ['name', 'bullets']));
const coverLetter = pick(b.coverLetter, ['date', 'addressee', 'salutation', 'paragraphs', 'signOff', 'name']);

// An unpaired UTF-16 surrogate cannot be stored by PostgreSQL JSON.
const lone = (str) => {
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff) {
      const n = str.charCodeAt(i + 1);
      if (n >= 0xdc00 && n <= 0xdfff) { i++; continue; }
      return true;
    }
    if (c >= 0xdc00 && c <= 0xdfff) return true;
  }
  return false;
};
// PostgreSQL text cannot hold a NUL character.
const NUL = String.fromCharCode(0);
const stack = [cv, coverLetter];
while (stack.length) {
  const x = stack.pop();
  if (typeof x === 'string') { if (x.indexOf(NUL) >= 0 || lone(x)) return fail(400, 'bad_request'); }
  else if (Array.isArray(x)) for (const y of x) stack.push(y);
  else if (isObj(x)) for (const k of Object.keys(x)) stack.push(x[k]);
}
return { json: { ok: true, jobId: q.id, fromVersionId: b.fromVersionId, cv, coverLetter } };

// The worker's check request: the same input the Generate workflow builds, with the edited documents.
const r = $json;
const req = $('Check edit request').first().json;
const fail = (code, error) => ({ json: { ok: false, code, body: { error } } });
if (r.error) return fail(500, 'server_error');
if (!r.job_found) return fail(404, 'job_not_found');
if (!r.version_found) return fail(404, 'version_not_found');
if (!r.cv_structured) return fail(422, 'base_cv_not_ready');
const src = r.src;
const kc = src.keyword_coverage;
const covered = kc && Array.isArray(kc.covered) ? kc.covered.filter((k) => typeof k === 'string') : [];
const letter = r.cl_structured;
const body = {
  templateId: src.template_id,
  cv: req.cv,
  coverLetter: req.coverLetter,
  keywordsCovered: covered,
  job: { title: r.job.title, employer: r.job.employer, advertiser: r.job.advertiser, rawText: r.job.rawText ?? '' },
  baseCv: { structured: r.cv_structured },
  // The base cover letter goes only as its analysis, never as its text (as in Generate).
  baseCoverLetter: letter
    ? { structured: { previousTarget: letter.previousTarget ?? null, reusableParagraphs: letter.reusableParagraphs ?? [], toneNotes: letter.toneNotes ?? '' } }
    : null,
  otherJobs: Array.isArray(r.other_jobs) ? r.other_jobs : [],
};
return { json: { ok: true, body } };

// The worker's check results. A document the worker rejects is a 400 naming the path; any other failure is a 500.
const res = $json;
const b = res.body;
const fail = (code, body) => ({ json: { ok: false, code, body } });
if (res.statusCode === 400 && b && b.error === 'invalid_document' && typeof b.path === 'string'
    && /^(cv|coverLetter)([.[]|$)/.test(b.path) && /^[A-Za-z0-9_.\[\]]{1,200}$/.test(b.path)) {
  return fail(400, { error: 'invalid_document', path: b.path });
}
const httpOk = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300;
if (!httpOk || !b || !Array.isArray(b.checks)) return fail(500, { error: 'server_error' });
return { json: { ok: true, checks: b.checks } };

// The new version's fields: the checks, the reasons with Prayush's manual edits (kept by text), the source's review.
const res = $json;
const b = res.body;
const fail = (code, body) => ({ json: { ok: false, code, body } });
const httpOk = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300;
if (!httpOk || !b || !Array.isArray(b.paths)) return fail(500, { error: 'server_error' });
const req = $('Check edit request').first().json;
const src = $('Load edit inputs').first().json.src;
const checks = $('Read edit check results').first().json.checks;
const isObj = (x) => typeof x === 'object' && x !== null && !Array.isArray(x);
// Manual edits are kept by text: { path, text } (text: what Prayush wrote there, null for a field he
// emptied). An edit is where its text is: at its path, or moved within the same list (a reordered or
// shifted bullet). Rows saved before this held paths only; they are read as the text at that path.
const meParts = (p) => String(p).match(/[^.[\]]+|\[\d+\]/g) || [];
const meAt = (docs, p) => {
  const parts = meParts(p);
  if (parts.length === 0) return { found: false };
  let x = docs;
  for (const part of parts) {
    if (part[0] === '[') {
      const i = Number(part.slice(1, -1));
      if (!Array.isArray(x) || i >= x.length) return { found: false };
      x = x[i];
    } else {
      if (typeof x !== 'object' || x === null || Array.isArray(x) || !Object.prototype.hasOwnProperty.call(x, part)) return { found: false };
      x = x[part];
    }
  }
  return { found: true, value: x };
};
// Every text field at or under a path, as { path, text }.
const meLeaves = (v, p, out = []) => {
  if (typeof v === 'string' || v === null) out.push({ path: p, text: v });
  else if (Array.isArray(v)) v.forEach((x, i) => meLeaves(x, `${p}[${i}]`, out));
  else if (typeof v === 'object' && v !== undefined) for (const k of Object.keys(v)) meLeaves(v[k], `${p}.${k}`, out);
  return out;
};
// The list a list item is in ("cv.experience[0].bullets" for "cv.experience[0].bullets[2]"), else null.
const meList = (p) => (/\[\d+\]$/.test(p) ? p.replace(/\[\d+\]$/, '') : null);
const meRead = (raw, docs) => {
  const out = [];
  const seen = new Set();
  for (const e of Array.isArray(raw) ? raw : []) {
    let items = [];
    if (typeof e === 'string') {
      const at = meAt(docs, e);
      if (at.found) items = meLeaves(at.value, e);
    } else if (e && typeof e === 'object' && typeof e.path === 'string' && (typeof e.text === 'string' || e.text === null)) {
      items = [{ path: e.path, text: e.text }];
    }
    for (const it of items) if (!seen.has(it.path)) { seen.add(it.path); out.push(it); }
  }
  return out;
};
// Where each edit is in these documents: { path, text } (path updated if it moved), or null when its text is gone.
const meLocate = (edits, docs) => {
  const here = edits.map((e) => { const at = meAt(docs, e.path); return at.found && at.value === e.text; });
  const used = new Set(edits.filter((e, i) => here[i]).map((e) => e.path));
  return edits.map((e, i) => {
    if (here[i]) return { path: e.path, text: e.text };
    const list = typeof e.text === 'string' ? meList(e.path) : null;
    const items = list ? meAt(docs, list) : { found: false };
    if (!items.found || !Array.isArray(items.value)) return null;
    const j = items.value.findIndex((v, k) => v === e.text && !used.has(`${list}[${k}]`));
    if (j < 0) return null;
    used.add(`${list}[${j}]`);
    return { path: `${list}[${j}]`, text: e.text };
  });
};
const before = { cv: src.cv, coverLetter: src.cover_letter };
const after = { cv: req.cv, coverLetter: req.coverLetter };
// The source's edits, where their text is now (an old path-only row: the text at that path in the source).
const earlier = meLocate(meRead(isObj(src.reasons) ? src.reasons.manualEdits : [], before), after).filter(Boolean);
// New edits: every text field at a changed path, unless the source already had that text in the same list
// (a bullet that only moved, for example because one above it was removed, is not an edit).
const fresh = [];
for (const p of b.paths.filter((x) => typeof x === 'string')) {
  const at = meAt(after, p);
  if (!at.found) continue;
  for (const leaf of meLeaves(at.value, p)) {
    const was = meAt(before, leaf.path);
    if (was.found && was.value === leaf.text) continue;
    const list = typeof leaf.text === 'string' ? meList(leaf.path) : null;
    const items = list ? meAt(before, list) : { found: false };
    if (items.found && Array.isArray(items.value) && items.value.includes(leaf.text)) continue;
    fresh.push(leaf);
  }
}
const byPath = new Map();
for (const e of [...earlier, ...fresh]) byPath.set(e.path, e);
const manualEdits = [...byPath.values()].sort((x, y) => (x.path < y.path ? -1 : x.path > y.path ? 1 : 0));
const reasons = { ...(isObj(src.reasons) ? src.reasons : {}), manualEdits };
const review0 = isObj(src.review) ? src.review : {};
// The review covers the version it was written for. An edit of an edit keeps that number.
const review = { ...review0, reviewedVersionNo: Number.isInteger(review0.reviewedVersionNo) ? review0.reviewedVersionNo : src.version_no };
return { json: {
  ok: true,
  checks,
  params: [
    '00000000-0000-0000-0000-000000000001', req.jobId, req.fromVersionId, 'edited', 'Edited',
    JSON.stringify(req.cv), JSON.stringify(req.coverLetter), JSON.stringify(reasons), JSON.stringify(review), JSON.stringify(checks), 'true',
  ],
} };

// Turns the insert's outcome into the HTTP answer. A clash on the version number (two saves at once) is tried again.
const r = $json;
if (r.error) {
  // The error item's shape varies, so look at all of it for the unique violation (SQLSTATE 23505).
  let msg = '';
  try { msg = JSON.stringify(r); } catch (e) { msg = String(r.error); }
  if (/23505|duplicate key/i.test(msg) && $runIndex < 12) return { json: { retry: true } };
  return { json: { retry: false, code: 500, body: { error: 'server_error' } } };
}
if (!r.found) return { json: { retry: false, code: 404, body: { error: r.job_found ? 'version_not_found' : 'job_not_found' } } };
if (!r.version_id) return { json: { retry: false, code: 500, body: { error: 'server_error' } } };
return { json: { retry: false, code: 201, body: { versionId: r.version_id, versionNo: r.version_no, checks: $('Build edited version').first().json.checks } } };

// Validates the restore request before the database is touched.
const q = $json.query || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const fail = (code, error) => ({ json: { ok: false, code, body: { error } } });
if (typeof q.id !== 'string' || !UUID.test(q.id)) return fail(404, 'job_not_found');
const b = $json.body;
if (typeof b !== 'object' || b === null || Array.isArray(b) || typeof b.versionId !== 'string' || !UUID.test(b.versionId)) return fail(400, 'bad_request');
return { json: { ok: true, params: ['00000000-0000-0000-0000-000000000001', q.id, b.versionId, 'restored', '', '', '', '', '', '', ''] } };

// Turns the insert's outcome into the HTTP answer. A clash on the version number (two saves at once) is tried again.
const r = $json;
if (r.error) {
  // The error item's shape varies, so look at all of it for the unique violation (SQLSTATE 23505).
  let msg = '';
  try { msg = JSON.stringify(r); } catch (e) { msg = String(r.error); }
  if (/23505|duplicate key/i.test(msg) && $runIndex < 12) return { json: { retry: true } };
  return { json: { retry: false, code: 500, body: { error: 'server_error' } } };
}
if (!r.found) return { json: { retry: false, code: 404, body: { error: r.job_found ? 'version_not_found' : 'job_not_found' } } };
if (!r.version_id) return { json: { retry: false, code: 500, body: { error: 'server_error' } } };
return { json: { retry: false, code: 201, body: { versionId: r.version_id, versionNo: r.version_no } } };
